"""
check_style.py — Spanish writing quality checks for k8s docs.

Checks:
  STYLE-001  Untranslated English term blocks (4+ consecutive English words)
  STYLE-002  Register inconsistency (tú vs usted forms in the same file)
  STYLE-003  Terminology inconsistency (clúster vs cluster, etc.)
  STYLE-004  Common typographic errors (double spaces, missing accent on common words)
  STYLE-005  Code block content modified (command names must match EN source)
  STYLE-006  English phrases inside prose paragraphs (not in code blocks)

Outputs: {"findings": [...], "errors": [...]}
"""

import argparse
import json
import math
import re
from pathlib import Path

CONTEXT_RADIUS = 2


def context_window(prose_lines: list[tuple[int, str]], line_no: int) -> dict:
    entries = list(prose_lines)
    positions = {ln: idx for idx, (ln, _) in enumerate(entries)}
    idx = positions.get(line_no)
    if idx is None:
        return {"context_before": [], "context_after": []}
    start = max(0, idx - CONTEXT_RADIUS)
    end = min(len(entries), idx + CONTEXT_RADIUS + 1)
    before = [
        {"line": ln, "text": text.rstrip()}
        for ln, text in entries[start:idx]
    ]
    after = [
        {"line": ln, "text": text.rstrip()}
        for ln, text in entries[idx + 1 : end]
    ]
    return {"context_before": before, "context_after": after}

